package com.havanduyet.quanlynhansu;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.*;import java.util.*;
public class EmployeeFormActivity extends Activity {
 private EmployeeDb db;private String oldCode=null,photo="";private EditText code,name,year,hometown,education,salary;private Spinner department;private RadioGroup gender;private ImageView image;private static final int IMAGE_REQUEST=1001;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_form);db=new EmployeeDb(this);code=findViewById(R.id.edtCode);name=findViewById(R.id.edtName);year=findViewById(R.id.edtYear);hometown=findViewById(R.id.edtHometown);education=findViewById(R.id.edtEducation);salary=findViewById(R.id.edtSalary);department=findViewById(R.id.spDepartment);gender=findViewById(R.id.radioGender);image=findViewById(R.id.previewPhoto);department.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,EmployeeDb.DEPARTMENTS));oldCode=getIntent().getStringExtra("code");((TextView)findViewById(R.id.txtTitle)).setText(oldCode==null?"THÊM NHÂN SỰ":"CẬP NHẬT NHÂN SỰ");if(oldCode!=null){Employee e=db.get(oldCode);if(e==null){finish();return;}code.setText(e.code);code.setEnabled(false);name.setText(e.name);year.setText(String.valueOf(e.birthYear));hometown.setText(e.hometown);education.setText(e.education);salary.setText(String.valueOf(e.salary));photo=e.photoUri==null?"":e.photoUri;showPhoto();if("Nữ".equals(e.gender))gender.check(R.id.radioFemale);else if("Khác".equals(e.gender))gender.check(R.id.radioOther);for(int j=0;j<EmployeeDb.DEPARTMENTS.length;j++)if(EmployeeDb.DEPARTMENTS[j].equals(e.department))department.setSelection(j);}findViewById(R.id.btnPhoto).setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,IMAGE_REQUEST);});findViewById(R.id.btnSave).setOnClickListener(v->save());findViewById(R.id.btnCancel).setOnClickListener(v->finish());}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==IMAGE_REQUEST&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}photo=uri.toString();showPhoto();}}
 private void showPhoto(){if(photo.isEmpty())image.setImageResource(android.R.drawable.ic_menu_gallery);else try{image.setImageURI(Uri.parse(photo));}catch(Exception ex){image.setImageResource(android.R.drawable.ic_menu_gallery);}}
 private String value(EditText e){return e.getText().toString().trim();}
 private void save(){String c=value(code),n=value(name),y=value(year),h=value(hometown),ed=value(education),s=value(salary);if(c.isEmpty()||n.isEmpty()||y.isEmpty()||h.isEmpty()||ed.isEmpty()||s.isEmpty()){Toast.makeText(this,"Vui lòng nhập đủ các trường có dấu *",Toast.LENGTH_LONG).show();return;}int birth;long money;try{birth=Integer.parseInt(y);money=Long.parseLong(s);}catch(NumberFormatException ex){Toast.makeText(this,"Năm sinh hoặc mức lương không hợp lệ",Toast.LENGTH_LONG).show();return;}int thisYear=Calendar.getInstance().get(Calendar.YEAR);if(birth<1900||birth>thisYear){year.setError("Năm sinh phải từ 1900 đến "+thisYear);return;}if(money<0){salary.setError("Lương không được âm");return;}if(oldCode==null&&db.get(c)!=null){code.setError("Mã nhân sự đã tồn tại");return;}String g=gender.getCheckedRadioButtonId()==R.id.radioFemale?"Nữ":gender.getCheckedRadioButtonId()==R.id.radioOther?"Khác":"Nam";Employee e=new Employee(c,n,birth,g,h,ed,photo,money,department.getSelectedItem().toString());boolean ok=oldCode==null?db.add(e):db.update(oldCode,e);Toast.makeText(this,ok?"Lưu thành công":"Không lưu được dữ liệu",Toast.LENGTH_SHORT).show();if(ok)finish();}
}
